Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:200px;line-height:1.3">Step through the cycle: each click advances one process, highlighting the active piston, its work arrow, and the reservoir or insulation block it sits in.</p>
<div style="display:flex;align-items:center;gap:6px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-weight:bold">1 / 4</span>
  <button onclick="nextStep()">▶</button>
</div>
<label>View: p–V diagram
  <input id="viewModeInput" type="checkbox" onchange="update_view(this.checked)">
</label>
<label>Process: Adiabatic (insulated)
  <input id="processTypeInput" type="checkbox" onchange="update_process(this.checked)">
</label>
<div style="display:flex;align-items:center;gap:6px">
  <button id="stepButtonInput" onclick="cycleStep()">Cycle step</button>
  <span id="stepName" style="font-weight:bold">Step 1: M→N</span>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, 1000, 580);

  // ---------- palette ----------
  var COL = {
    resHotFill: '#f3bcbc', resHotEdge: '#d98080',
    insFill: '#fbe3d6', insEdge: '#b9b9b9',
    resColdFill: '#a9cfe0', resColdEdge: '#5f93ad',
    gas: '#b3b3b3', gasEdge: '#7d7d7d', dot: '#6f6f6f',
    piston: '#c9c9e2', pistonEdge: '#8a8ab0',
    work: '#3f9e3a', heat: '#666666',
    accent: '#e63946', axis: '#333333', loopFill: '#ffe9a8'
  };

  // ---------- deterministic dots ----------
  function makeRng(seed) { var s = seed >>> 0; return function () { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }

  // ---------- arrow helper ----------
  function arrow(g, x, y1, y2, color, w, headLen) {
    headLen = headLen || 12;
    var dir = (y2 < y1) ? -1 : 1;
    g.line(x, y1, x, y2 - dir * headLen).stroke({ color: color, width: w, linecap: 'round' });
    var hy = y2;
    g.polygon([
      [x, hy],
      [x - w * 1.6, hy - dir * headLen],
      [x + w * 1.6, hy - dir * headLen]
    ].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
  }

  // ---------- panel data ----------
  var panels = [
    { x: 15,  kind: 'resHot',  gasH: 110, workDir: 'up',   heatDir: 'up',   cap: ['Step 1:', 'Isothermal', 'expansion', '(M→N)'], temp: '(Temperature T\u2095)' },
    { x: 260, kind: 'ins',     gasH: 170, workDir: 'up',   heatDir: null,   cap: ['Step 2:', 'Adiabatic', 'expansion', '(N→O)'], temp: null },
    { x: 505, kind: 'resCold', gasH: 120, workDir: 'down', heatDir: 'down', cap: ['Step 3:', 'Isothermal', 'compression', '(O→P)'], temp: '(Temperature T\u1D04)' },
    { x: 750, kind: 'ins',     gasH: 70,  workDir: 'down', heatDir: null,   cap: ['Step 4:', 'Adiabatic', 'compression', '(P→M)'], temp: null }
  ];
  var PW = 225, BLOCK_TOP = 15, BLOCK_BOT = 420;

  var pistonGroup = draw.group();
  var heatGroup = draw.group();
  var q0Group = draw.group();
  var ringGroup = draw.group();
  var pvGroup = draw.group();

  var panelGeo = [];

  panels.forEach(function (p, i) {
    var fill = p.kind === 'resHot' ? COL.resHotFill : p.kind === 'resCold' ? COL.resColdFill : COL.insFill;
    var edge = p.kind === 'resHot' ? COL.resHotEdge : p.kind === 'resCold' ? COL.resColdEdge : COL.insEdge;
    var g = pistonGroup.group();

    // surrounding block
    g.rect(PW, BLOCK_BOT - BLOCK_TOP).move(p.x, BLOCK_TOP).fill(fill).stroke({ color: edge, width: 2 });

    var cx = p.x + PW / 2;
    var cylW = 72, cylL = cx - cylW / 2, cylR = cx + cylW / 2;
    var cylTop = 25, cylBot = 300, gasBot = 290;
    var gasTop = gasBot - p.gasH;

    // gas column
    g.rect(cylW, gasBot - gasTop).move(cylL, gasTop).fill(COL.gas).stroke({ color: COL.gasEdge, width: 1.5 });
    // dots
    var rng = makeRng(1000 + i * 77);
    var cols = 6, rows = Math.max(3, Math.round((gasBot - gasTop) / 16));
    for (var r = 0; r < rows; r++) {
      for (var c = 0; c < cols; c++) {
        var dx = cylL + 8 + (c + 0.5) * ((cylW - 16) / cols) + (rng() - 0.5) * 6;
        var dy = gasTop + 8 + (r + 0.5) * ((gasBot - gasTop - 16) / rows) + (rng() - 0.5) * 6;
        g.circle(3.2).center(dx, dy).fill(COL.dot);
      }
    }
    // cylinder walls (open top)
    g.line(cylL, cylTop, cylL, cylBot).stroke({ color: COL.gasEdge, width: 2 });
    g.line(cylR, cylTop, cylR, cylBot).stroke({ color: COL.gasEdge, width: 2 });
    g.line(cylL, cylBot, cylR, cylBot).stroke({ color: COL.gasEdge, width: 2 });

    // piston + stem
    var pistH = 14;
    g.rect(cylW + 6, pistH).move(cylL - 3, gasTop - pistH).fill(COL.piston).stroke({ color: COL.pistonEdge, width: 1.5 });
    var stemTop = gasTop - pistH - 26;
    g.rect(8, 26).move(cx - 4, stemTop).fill(COL.piston).stroke({ color: COL.pistonEdge, width: 1 });

    // work arrow (green) with Unicode subscripts
    var wSubs = ['\u2081', '\u2082', '\u2083', '\u2084'];
    var wLabel = 'W' + wSubs[i];
    var wTop = stemTop - 6;
    if (p.workDir === 'up') {
      arrow(g, cx, wTop, wTop - 44, COL.work, 4);
      g.text(wLabel).font({ size: 20, weight: 'bold', family: 'sans-serif' }).fill('#222')
        .center(cx, wTop - 56).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
    } else {
      arrow(g, cx, wTop - 44, wTop, COL.work, 4);
      g.text(wLabel).font({ size: 20, weight: 'bold', family: 'sans-serif' }).fill('#222')
        .center(cx, wTop - 56).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
    }

    // heat arrow (gray) for isothermal — Q label offset to the RIGHT of arrow
    if (p.heatDir) {
      var hg = heatGroup.group();
      if (p.heatDir === 'up') {
        arrow(hg, cx, 385, 325, COL.heat, 6, 14);
        hg.text('Q\u2095').font({ size: 20, family: 'sans-serif' }).fill('#222')
          .center(cx + 32, 370).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
      } else {
        arrow(hg, cx, 325, 385, COL.heat, 6, 14);
        hg.text('Q\u1D04').font({ size: 20, family: 'sans-serif' }).fill('#222')
          .center(cx + 32, 370).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
      }
    }
    // Q=0 badge (adiabatic mode)
    var q0 = q0Group.text('Q = 0').font({ size: 16, weight: 'bold', family: 'sans-serif' }).fill('#8a4a2a').center(cx, 355);
    q0.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });

    // reservoir / insulation label inside block bottom
    var lab = (p.kind === 'ins') ? 'Insulation' : 'Reservoir';
    g.text(lab).font({ size: 18, family: 'sans-serif' }).fill('#222').center(cx, BLOCK_BOT - 14);

    // temperature label — moved UP into the block to avoid collision with captions
    if (p.temp) {
      g.text(p.temp).font({ size: 14, family: 'sans-serif' }).fill('#333').center(cx, BLOCK_BOT + 16);
    }

    // captions below block — pushed down for spacing
    var cy = BLOCK_BOT + 42;
    g.text(p.cap[0]).font({ size: 17, weight: 'bold', family: 'sans-serif' }).fill('#111').center(cx, cy);
    g.text(p.cap[1]).font({ size: 15, family: 'sans-serif' }).fill('#111').center(cx, cy + 20);
    g.text(p.cap[2]).font({ size: 15, family: 'sans-serif' }).fill('#111').center(cx, cy + 38);
    g.text(p.cap[3]).font({ size: 15, family: 'sans-serif' }).fill('#111').center(cx, cy + 56);

    panelGeo.push({ x: p.x, cx: cx });

    // hover / click on block
    g.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Step ' + (i + 1) + ': ' + p.cap[1] + ' ' + p.cap[2] + ' ' + p.cap[3], e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { setStep(i + 1); });
  });

  // active-step ring
  var ring = ringGroup.rect(PW + 8, BLOCK_BOT - BLOCK_TOP + 8).fill('none')
    .stroke({ color: COL.accent, width: 4, dasharray: '0' }).radius(4);
  ring.node.style.transition = 'all .3s';

  // ================= p-V diagram =================
  var pvX0 = 130, pvY0 = 480, pvX1 = 920, pvY1 = 50;
  var Vmin = 0.5, Vmax = 4.6, pmin = 0, pmax = 3.5;
  function pvX(v) { return pvX0 + (v - Vmin) / (Vmax - Vmin) * (pvX1 - pvX0); }
  function pvY(p) { return pvY0 - (p - pmin) / (pmax - pmin) * (pvY0 - pvY1); }

  var corners = { M: [1.0, 3.0], N: [2.6, 1.15], O: [4.0, 0.55], P: [1.4, 0.95] };
  var legs = [
    { a: 'M', b: 'N', c: [1.8, 1.55], name: 'M\u2192N (isothermal, T\u2095)' },
    { a: 'N', b: 'O', c: [3.4, 0.62], name: 'N\u2192O (adiabatic)' },
    { a: 'O', b: 'P', c: [2.5, 0.50], name: 'O\u2192P (isothermal, T\u1D04)' },
    { a: 'P', b: 'M', c: [1.0, 1.85], name: 'P\u2192M (adiabatic)' }
  ];
  function legPath(L) {
    var A = corners[L.a], B = corners[L.b], C = L.c;
    return 'M ' + pvX(A[0]) + ' ' + pvY(A[1]) + ' Q ' + pvX(C[0]) + ' ' + pvY(C[1]) + ' ' + pvX(B[0]) + ' ' + pvY(B[1]);
  }

  // axes
  pvGroup.line(pvX0, pvY1 - 10, pvX0, pvY0).stroke({ color: COL.axis, width: 2 });
  pvGroup.line(pvX0, pvY0, pvX1 + 10, pvY0).stroke({ color: COL.axis, width: 2 });
  arrow(pvGroup, pvX0, pvY0, pvY1 - 18, COL.axis, 2, 10);
  arrow(pvGroup, pvX0, pvY0, pvX1 + 18, COL.axis, 2, 10);
  pvGroup.text('p').font({ size: 22, style: 'italic', family: 'serif' }).fill('#111').center(pvX0 - 18, pvY1 - 6);
  pvGroup.text('V').font({ size: 22, style: 'italic', family: 'serif' }).fill('#111').center(pvX1 + 18, pvY0 + 16);

  // enclosed area (net work)
  var areaPath = '';
  legs.forEach(function (L, i) {
    var A = corners[L.a], B = corners[L.b], C = L.c;
    areaPath += (i === 0 ? 'M ' : 'L ') + pvX(A[0]) + ' ' + pvY(A[1]) + ' Q ' + pvX(C[0]) + ' ' + pvY(C[1]) + ' ' + pvX(B[0]) + ' ' + pvY(B[1]) + ' ';
  });
  areaPath += 'Z';
  pvGroup.path(areaPath).fill({ color: COL.loopFill, opacity: 0.55 }).stroke('none')
    .on('mousemove', function (e) { showTooltip('Enclosed area = net work output per cycle', e); })
    .on('mouseleave', hideTooltip);

  // base loop strokes
  var legEls = legs.map(function (L) {
    return pvGroup.path(legPath(L)).fill('none').stroke({ color: '#444', width: 2.5, linecap: 'round' });
  });
  // active highlight leg
  var activeLeg = pvGroup.path(legPath(legs[0])).fill('none')
    .stroke({ color: COL.accent, width: 5, linecap: 'round' });
  activeLeg.node.style.transition = 'all .3s';

  // corner labels + dots
  Object.keys(corners).forEach(function (k) {
    var v = corners[k];
    pvGroup.circle(7).center(pvX(v[0]), pvY(v[1])).fill('#222');
    var off = { M: [-16, -12], N: [16, -12], O: [16, 14], P: [-16, 14] }[k];
    pvGroup.text(k).font({ size: 20, weight: 'bold', style: 'italic', family: 'serif' }).fill('#111')
      .center(pvX(v[0]) + off[0], pvY(v[1]) + off[1])
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  });
  // isotherm tags
  pvGroup.text('T\u2095').font({ size: 16, style: 'italic', family: 'serif' }).fill('#a03030').center(pvX(1.7), pvY(2.0));
  pvGroup.text('T\u1D04').font({ size: 16, style: 'italic', family: 'serif' }).fill('#2a6a8a').center(pvX(2.7), pvY(0.78));

  // ================= state & controls =================
  var currentStep = 1;
  var isAdiabatic = false;
  var isPV = false;
  var stepNames = ['Step 1: M\u2192N', 'Step 2: N\u2192O', 'Step 3: O\u2192P', 'Step 4: P\u2192M'];

  function setStep(n) {
    currentStep = ((n - 1) % 4 + 4) % 4 + 1;
    var geo = panelGeo[currentStep - 1];
    ring.move(geo.x - 4, BLOCK_TOP - 4);
    activeLeg.attr({ d: legPath(legs[currentStep - 1]) });
    document.getElementById('stepName').textContent = stepNames[currentStep - 1];
    document.getElementById('stepLabel').textContent = currentStep + ' / 4';
  }
  function cycleStep() { setStep(currentStep + 1); }
  function update_process(on) {
    isAdiabatic = on;
    heatGroup.node.style.opacity = on ? 0 : 1;
    heatGroup.node.style.pointerEvents = on ? 'none' : 'auto';
    q0Group.node.style.opacity = on ? 1 : 0;
  }
  function update_view(on) {
    isPV = on;
    pistonGroup.node.style.opacity = on ? 0 : 1;
    ringGroup.node.style.opacity = on ? 0 : 1;
    heatGroup.node.style.opacity = (on || isAdiabatic) ? 0 : 1;
    q0Group.node.style.opacity = (on || !isAdiabatic) ? 0 : 1;
    pistonGroup.node.style.pointerEvents = on ? 'none' : 'auto';
    pvGroup.node.style.opacity = on ? 1 : 0;
    pvGroup.node.style.pointerEvents = on ? 'auto' : 'none';
  }
  [pistonGroup, ringGroup, heatGroup, q0Group, pvGroup].forEach(function (g) {
    g.node.style.transition = 'opacity .4s';
  });

  // demo step player
  var demoSteps = [
    { t: 'The four legs in order', n: 'Step through the cycle: each click advances one process, highlighting the active piston, its work arrow, and the reservoir or insulation block it sits in, making the expansion-then-compression ordering explicit.', view: false, adia: false, step: 1 },
    { t: 'Heat crosses only on isothermal legs', n: 'Switch to the adiabatic view: Steps 2 and 4 sit inside insulation blocks with no heat arrow, while the isothermal view shows Q\u2095 entering at T\u2095 and Q\u1D04 leaving at T\u1D04 \u2014 heat transfer is confined to the two reservoir legs.', view: false, adia: true, step: 2 },
    { t: 'Map piston motion to the p\u2013V path', n: 'Toggle to the p\u2013V diagram and step through again: each selected cylinder state highlights the matching segment of the MNOP loop \u2014 the upper T\u2095 isotherm, lower T\u1D04 isotherm, and the two steeper adiabats connecting them.', view: true, adia: false, step: 1 },
    { t: 'Close the loop', n: 'Advance to Step 4 (P\u2192M): the final adiabat returns the gas to state M, closing the loop \u2014 the area enclosed by MNOP is the net work the engine delivers per cycle.', view: true, adia: true, step: 4 }
  ];
  var demoIdx = 0;
  function applyDemo(i) {
    demoIdx = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
    var s = demoSteps[demoIdx];
    document.getElementById('viewModeInput').checked = s.view;
    document.getElementById('processTypeInput').checked = s.adia;
    update_view(s.view);
    update_process(s.adia);
    setStep(s.step);
    document.getElementById('demoNarration').textContent = s.n;
  }
  function nextStep() { applyDemo(demoIdx + 1); }
  function prevStep() { applyDemo(demoIdx - 1); }
  window.nextStep = nextStep; window.prevStep = prevStep;
  window.cycleStep = cycleStep; window.update_view = update_view; window.update_process = update_process;
  window.setStep = setStep;

  // init default = faithful image (piston view, isothermal, step 1)
  update_view(false);
  update_process(false);
  setStep(1);
  applyDemo(0);

  window.__markRendered();
})();
// @FIGURE_CODE_END

